import org.eclipse.rdf4j.sail.SailConnection;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbBulkApprovalBatchTest {

	private static final int ROW_COUNT = 1024;
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:bulk-approval:p");
	private static final IRI OBJECT = VF.createIRI("urn:bulk-approval:o");

	@TempDir
	Path tempDir;

	@Test
	void noneAndSnapshotBulkApprovalRetainExactStatementsAfterReopen() throws Exception {
		verifyBulkApproval(IsolationLevels.NONE, "none");
		verifyBulkApproval(IsolationLevels.SNAPSHOT, "snapshot");
	}

	private void verifyBulkApproval(IsolationLevel isolationLevel, String directoryName) throws Exception {
		LmdbStore store = new LmdbStore(tempDir.resolve(directoryName).toFile());
		store.init();
		try {
			ObservedStatementSet statements = new ObservedStatementSet(rows());
			try (SailConnection connection = store.getConnection()) {
				connection.begin(isolationLevel);
				connection.addStatements(statements);
				connection.commit();
				assertObservedTraversal(statements);
				if (IsolationLevels.SNAPSHOT.equals(isolationLevel)) {
					assertTrue(statements.sizeCalls() > 0,
							"snapshot bulk approval should use the supplied set size for its prepared batch");
				}
				assertEquals(rows(), readStatements(connection));
			}

			store.shutDown();
			store.init();
			try (SailConnection connection = store.getConnection()) {
				assertEquals(rows(), readStatements(connection), "reopened store must retain the exact input set");
			}
		} finally {
			store.shutDown();
		}
	}

	private static void assertObservedTraversal(ObservedStatementSet statements) {
		assertEquals(1, statements.iteratorCalls(), "the source set should be traversed once");
		assertEquals(ROW_COUNT, statements.consumedRows(), "every source statement should be consumed exactly once");
	}

	private static Set<Statement> rows() {
		Set<Statement> rows = new LinkedHashSet<>(ROW_COUNT);
		for (int i = 0; i < ROW_COUNT; i++) {
			Resource subject = VF.createIRI("urn:bulk-approval:s:" + i);
			rows.add(VF.createStatement(subject, PREDICATE, OBJECT));
		}
		return Set.copyOf(rows);
	}

	private static Set<Statement> readStatements(SailConnection connection) throws Exception {
		Set<Statement> statements = new LinkedHashSet<>();
		try (CloseableIteration<? extends Statement> result = connection.getStatements(null, null, null, false)) {
			while (result.hasNext()) {
				statements.add(result.next());
			}
		}
		return Set.copyOf(statements);
	}

	private static final class ObservedStatementSet extends AbstractSet<Statement> {
		private final Set<Statement> delegate;
		private final AtomicInteger sizeCalls = new AtomicInteger();
		private final AtomicInteger iteratorCalls = new AtomicInteger();
		private final AtomicInteger consumedRows = new AtomicInteger();

		private ObservedStatementSet(Set<Statement> statements) {
			delegate = new LinkedHashSet<>(statements);
		}

		@Override
		public Iterator<Statement> iterator() {
			iteratorCalls.incrementAndGet();
			Iterator<Statement> source = delegate.iterator();
			return new Iterator<>() {
				@Override
				public boolean hasNext() {
					return source.hasNext();
				}

				@Override
				public Statement next() {
					consumedRows.incrementAndGet();
					return source.next();
				}
			};
		}

		@Override
		public int size() {
			sizeCalls.incrementAndGet();
			return delegate.size();
		}

		private int sizeCalls() {
			return sizeCalls.get();
		}

		private int iteratorCalls() {
			return iteratorCalls.get();
		}

		private int consumedRows() {
			return consumedRows.get();
		}
	}
}
